Tool response:
Tool: update_event_type_availability
Description: Update the availability schedule for a specific event type.
Parameters:
    {
      "type": "object",
      "properties": {
        "event_type_id": {
          "type": "integer",
          "description": "The ID of the event type to update",
          "title": "Event Type Id"
        },
        "start_date": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Start Date"
        },
        "days_to_disable": {
          "anyOf": [
            {
              "items": {
                "type": "integer"
              },
              "type": "array"
            },
            {
              "type": "null"
            }
          ],
          "title": "Days To Disable"
        },
        "time_range": {
          "anyOf": [
            {
              "properties": {
                "start_time": {
                  "type": "string",
                  "title": "Start Time"
                },
                "end_time": {
                  "type": "string",
                  "title": "End Time"
                }
              },
              "type": "object",
              "required": [
                "start_time",
                "end_time"
              ],
              "title": "TimeRange"
            },
            {
              "type": "null"
            }
          ]
        }
      },
      "required": [
        "event_type_id"
      ]
    }

Tool response:
Tool: get_event_type_availability
Description: Retrieve the current availability schedule for a specific event type.
Parameters:
    {
      "type": "object",
      "properties": {
        "event_type_id": {
          "type": "integer",
          "description": "The ID of the event type to retrieve availability for",
          "title": "Event Type Id"
        }
      },
      "required": [
        "event_type_id"
      ]
    }

Tool response:
Tool: create_event_type
Description: Create a new event type with specified details including duration and timezone.
Parameters:
    {
      "type": "object",
      "properties": {
        "user_id": {
          "type": "integer",
          "title": "User Id"
        },
        "name": {
          "type": "string",
          "title": "Name"
        },
        "description": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Description"
        },
        "duration": {
          "type": "integer",
          "title": "Duration"
        },
        "timezone": {
          "type": "string",
          "title": "Timezone",
          "default": "UTC"
        }
      },
      "required": [
        "user_id",
        "name",
        "duration"
      ]
    }
